    """Parse YYYY-MM-DD, YYYY/MM/DD or DD.MM.YYYY into integer (year, month, day)."""
    text = text.strip()
    if "/" in text:
        text = text.replace("/", "-")
    elif "." in text:
        day, month, year = text.split(".")
        text = "-".join((year, month, day))

    # Normalize locally so the shared ISO-only helper also supports import formats.
    year, month, day = split_date(text)
